          '《史记》只用五个字记录他这十年：「持汉节不失。」那根缀着牦牛尾的使节杖，他一直握着。十年后看守松弛，他带着部属西逃。值得注意的是逃亡的方向：他没有东逃回国，而是继续向西——去完成那个同盟几乎已经失去意义的任务。',
          '与胡妻、堂邑父西走数十日，抵达费尔干纳盆地的大宛。大宛王久闻汉朝富饶，「欲通不得」，见到张骞大喜，问他想要什么，随即派译员向导送他经康居去大月氏。',
