          '但他没有空手。在大夏的市场上，他看见邛崃山的竹杖和蜀地的布，问从哪来，答：从东南的身毒国（印度）贩来。他立刻推算：蜀地西南必有一条通往身毒的路，走这条路近而安全。一条他自己没有走过的商路，被他记在了给皇帝的汇报里——后来汉武帝为此经营西南夷。',
          '他还系统记录了沿途各国的兵力、物产、风俗、道路：大宛的汗血马，安息（波斯）的位置，条支（地中海东岸）的传说。这是中原政权第一次拿到关于西方世界的成体系的情报。',
