          '武帝拜他为太中大夫，堂邑父为奉使君。前 123 年，张骞以校尉随卫青出击匈奴，因熟悉水草分布，「军得以不乏」，封博望侯；前 121 年随李广出右北平失期当斩，赎为庶人。官场沉浮没有耗掉他的价值——前 119 年，武帝拜他为中郎将，第二次出使，率三百人、牛羊万数、金币帛数千万，出使乌孙，副使分赴大宛、康居、大月氏、大夏、安息、身毒诸国。',
          '前 115 年张骞归汉，拜大行，位列九卿，岁余而卒。他没能看到的是：乌孙使者随他入汉，看到汉朝人多物盛；他派出的副使陆续归国，各国使者跟着来到长安。',
