          '后来他为写《淮阴侯列传》专程去淮阴，当地人告诉他韩信贫贱时母亲葬在高敞之地，他去看，坟旁果然可置万户；写《魏公子列传》特意去大梁之墟，访夷门——侯嬴守过的那座城门。史料之外，他要的是现场的证词与地气。',
