          '前 99 年，李陵率五千步卒出居延，深入漠北浚稽山，遭匈奴单于八万骑合围。血战八日，转斗千里，矢尽道穷，救兵不至，李陵投降。消息传回，满朝文武争着落井下石。武帝问司马迁的看法，他说了实话：李陵事亲孝、与士信，有国士之风；此刻不死，多半是「欲得当以报汉」——想找机会将功赎罪。',
          '这话说坏了。武帝认定他是替主帅李广利（他的宠姬兄长）开脱、贬低败军之将，以「沮贰师」之罪下狱。按汉律，此罪可赎死或代以腐刑；司马迁「家贫，货赂不足以自赎，交游莫救，左右亲近不为一言」——平日满座宾朋，无一人肯出五十万钱。',
          '一个史官对一场战败说了句公道话，被全国的沉默判了腐刑。他在狱中想明白了一件事：直接去死，是容易的；但那样死，「若九牛亡一毛，与蝼蚁何以异」。',
