          '李白的风格在这十年里炉火纯青：想象力挣脱一切物理规律——「黄河之水天上来」，「飞流直下三千尺，疑是银河落九天」，「燕山雪花大如席」。数字在他笔下不是修辞，是呼吸方式。盛唐给了他这样的肺活量：只有真正自信的时代，才容得下这么大口气的大话。',
