          '他存诗约千首。《将进酒》《蜀道难》《望庐山瀑布》《静夜思》——「床前明月光」很可能是每个中国孩子学会的第一首诗。一个诗人的语言，成了民族的母语：此后所有写月亮、写酒、写远行的中国人，都在不自觉地引用他。',
