          '735 年他考进士落第，没太当回事；此后十年游历快活，「饮酣视八极，俗物都茫茫」。746 年他来到长安，正式开始求仕。此时他三十五岁，诗已写得不坏，运气即将用尽。',
          '开元盛世给了他少年意气，但盛世的科举与选官制度，接下来会当着他的面表演两次荒诞。',
