          '此后他在长安困守近十年：投诗权贵，献《三大礼赋》得玄宗赏识，却只换来「待制集贤院」的空头名义。「朝扣富儿门，暮随肥马尘；残杯与冷炙，到处潜悲辛」——盛唐最伟大的诗人正在首都挨饿。755 年，朝廷终于给了他一个官：右卫率府胄曹参军，管仓库兵甲的小吏。',
          '同年冬他回奉先探家，进门听见哭声——幼子饿死了。他彻夜写下《自京赴奉先县咏怀五百字》，末尾正是那十个字：「朱门酒肉臭，路有冻死骨。」安史之乱尚未南下，这个王朝的死亡判词，已被一个挨饿的父亲提前写好。',
