          '然而航线的尽头暴露了航行的性质：七下西洋没有建立一处据点，没有开辟一条持续贸易线，所有交换都嵌在「朝贡—赏赐」的礼制框架里。史载赏赐所费以百万计，回航的香料苏木又被折成官员俸禄，搞得怨声载道。远航越盛大，国库越吃紧——这为日后的转向埋好了引线。',
