          '李斯是楚国上蔡人，年轻时做郡里的小吏。他后来向人讲过那个改变一生的下午：厕所里的老鼠吃着脏东西，见人犬靠近就惊恐逃散；官仓的老鼠住在高墙大屋，吃着囤积的粟米，见人来了也毫不惊扰。两相对照，他喟然长叹：「人之贤不肖譬如鼠矣，在所自处耳！」——人的贤与不肖，就像老鼠，取决于把自己放在什么位置。',
