          '另一笔账在前 406 年。阿吉纽西海战获胜，却因风暴未能打捞落水将士，雅典人要求集体审判六位将军。苏格拉底恰任主席团成员，他援引程序反对合议处决，独自投出反对票，遭到当众威胁。将军们最终仍被处死；几年后，有人把这笔违法的账，记到了「教唆者」们的头上。',
          '前 399 年，诗人迈雷托斯、演说家吕孔与政治家安尼托斯正式起诉，罪名两条：不敬城邦之神、引进新神；败坏青年。五百零一人的大陪审团听完申辩，以二百八十一票对二百二十票定罪——若再少三十票，他本可无罪开释。',
