          '柏拉图约于前 428 年生于雅典贵族之家，父系自称可上溯古雅典王族，母系出自立法者梭伦一门。他的少年在伯罗奔尼撒战争最惨烈的岁月里度过：瘟疫、围城、帝国由盛转衰。一个贵族子弟的成人礼，是亲眼看着秩序如何崩塌。',
          '二十岁那年他遇到苏格拉底，追随八年。这八年恰是最坏的年景：雅典战败，他的远房亲戚克里提亚斯与卡尔米德加入残暴的「三十僭主」，曾邀他入伙；民主复辟后这批人被清算，而处死苏格拉底的，又正是复辟的民主政权。僭主杀人，多数人也杀人——柏拉图后来在《第七封信》里写道，由此他对现存一切政体感到失望。',
          '老师死后，他离开雅典游历：麦加拉、昔勒尼、南意大利的毕达哥拉斯学派，据载还到过埃及。在南意大利他结识数学家阿尔基塔斯，毕达哥拉斯学派对数与秩序的信仰，就此嫁接到苏格拉底的伦理追问上。据后世传记，他还在西西里被僭主卖作奴隶，由友人赎回——第一次西西里之行，以耻辱收场。',
