          '从这里走出的名字贯穿此后的学术史：欧多克索斯在此重建比例论，亚里士多德在此就读二十年，欧几里得的几何传统也被史家归入学园一脉。柏拉图的教学不用讲义，用对话——抛出问题、暴露错误、逼向更精确的表述。他留下的三十余篇对话录（公认真作二十余部），既是哲学著作，也是课堂实录。',
          '这种写法本身就是立场：真理不在结论里，而在追问的往复里。他甚至在《第七封信》中说，最重大的东西绝不可形诸文字——写下的只是引路的标记。一位靠文字活了千年的作者说文字不是路本身，这话只有真正爱智者敢讲。',
