          '柏拉图形而上学的核心是一个两分的世界：感官所见的万物流变不居，只是「影子」；永恒不变的「理念」才是真实。《理想国》第七卷把它讲成一场戏：囚徒自幼被锁在洞中，只看得见火光投在洞壁上的影子，便以为影子就是全部世界；一旦有人挣脱锁链走出洞口，阳光下的真实反而刺得他睁不开眼。',
          '这则寓言同时是一幅知识地图：从影子到实物，从数理到理念，是灵魂的四级攀升；哲学家，就是走出过洞穴的人。它也顺手预言了老师的命运——走出洞穴的人回到洞穴，等待他的常常是石头。理念论的影响远超哲学：基督教神学对彼岸的构想、数学对理想对象的信仰，都能在这里找到源头。',
          '当然，它从第一天起就挨批评。亚里士多德逐条驳斥：理念若独立存在于事物之外，如何解释运动与知识？「吾爱吾师，吾更爱真理」的学案，正发生在这对师生之间——原文见于《尼各马可伦理学》：师友皆可亲，虔敬仍要求把真理置于朋友之上。',
