          '今天的大众语汇里仍有他的痕迹：「柏拉图式恋爱」出自《会饮篇》爱的阶梯——由肉体之美攀升至纯粹之美；「学院」一词是他的校名。一个死去两千三百多年的人，仍握着现代人的几个常用词。每当有人感叹「世界只是表象」，或追问「什么是正义」，他就再次开口。',
