          '她大兴土木：卡纳克立起当时最高的方尖碑——一对中至今还站着一根，近三十米；代尔巴哈利停灵庙则成了埃及建筑的巅峰，三层露台嵌进峭壁，廊柱与神龛层层收束。主持工程的总监森穆特是她最信任的大臣，也是公主的家庭教师——两人的关系，两千年后仍被写进小说。',
