          '今天的主流评价给了她迟到的公正：二十二年和平、贸易繁荣、无一场惨败、留下的建筑成为埃及地标——这份成绩单在三百多个法老里排得上前列。她证明了王冠不需要长在男人的下巴上，也证明了：连法老都拦不住继任者改写历史。',
