          '思想市场同样热闹。婆罗门的祭祀传统之外，无数沙门团体在恒河边辩论：轮回是真的吗？解脱靠什么？其中就有耆那教的祖师大雄。悉达多的出走，本质是加入这场全印度的精神竞赛——父亲为他修三座宫殿、备下举国的享乐，想留住他，注定留不住。',
