          '但他站在一个成熟的学科上。欧多克索斯的比例试验、泰阿泰德的无理数与正多面体研究，成果早已散落学界；亚历山大城新建的图书馆正把地中海的抄本往一处收。时代在等一个整理者——把两百年的数学发现，装配成一栋从地基盖起的房子。欧几里得接下了这个活。',
