          '更深的改造在思维习惯：定义先行、证据成链、从公理到结论——这套「讲道理的格式」渗进了近代科学、法学乃至政治文本。美国的《独立宣言》开头那串「我们认为不言自明」，在修辞结构上就是一条公设。爱因斯坦后来说，如果你少年时没有被欧几里得点燃，那你天生不适合做科学。',
