          '有趣的是，这次「失败」反而抬高了他的方法论：正因为体系从公理出发，换掉一条公设就能得到一个自洽的新世界——公理化方法的弹性，恰恰是被他示范出来的。今天中学生学的平面几何，内容与两千三百年前的《几何原本》几乎一致；而那位作者，连一张生平年表都没能给自己留下。他全部的传记，就是那本书。',
