          '《寰宇记》震撼欧洲的，不是传奇故事，而是一张「不可能」的清单：中国用纸做钱——一张纸被当作黄金流通，全凭帝国的信用与刑律；北方人烧一种黑色的石头（煤），比木柴耐烧；帝国以驿站网络传递文书，四十里一铺，昼夜兼程；火浣布（石棉）不是神话里的火蜥蜴毛，是一种可以捶碎织布的矿物——他甚至描述了产地与开采。',
          '他给中国起了两个名字：北方的「契丹」（Cathay）、南方的「蛮子」（Mangi）。这两个词在欧洲地图上存在了三百年，直到利玛窦时代才确认它们属于同一个中国。书以一百四十余种抄本流传，从修道院到宫廷——对 14 世纪的欧洲读者而言，这本书意味着：世界比《圣经》地理大得多。',
          '当然，也有他不认识的伟大：书中未提长城、未提茶、未提缠足与筷子。漏掉的东西，后来成了七百年疑案的起点。',
