        heading: '「我还没有说出我所见的一半」',
        paragraphs: [
          '从 14 世纪起就有人怀疑这本书：托斯卡纳修士说他写的是「不敬神的谎言」；1995 年，大英图书馆的吴芳思著《马可·波罗到过中国吗？》重提旧案。辩护者的证据是元朝档案里波罗家族的踪迹、他对围城之战等细节的独家记录。到过与否，学界至今未有一致结论。',
          '更确凿的是影响力。哥伦布藏有一部拉丁译本，页边写满批注——他向西启航要找的就是「契丹」与「汗八里」，找中国与日本，却撞上了美洲。一张错误的目的地清单，启动了地理大发现：马可·波罗的书在他身后一百年，还在制造历史。',
          '据说他临终时，朋友劝他坦白书中言过其实之处，他答：「我还没有说出我所见的一半。」无论这本书有几分成色，这句话是准的：那个时代的东方，比他的书更大。',
        ],
