          '1325 年，二十一岁的他循着朝觐路线出发：沿北非海岸经特莱姆森、突尼斯，到埃及的开罗与亚历山大。沿途参访圣墓与苏菲道堂，拜会学者。走到开罗时他做了决定：去麦加之后，不回家——再往前，看看世界还有多大。',
