          '1420 年代，美因茨城市内乱，贵族与行会争权，古腾堡一家流亡斯特拉斯堡。他在那里合伙做生意：打磨朝圣用的纪念镜，同时与合伙人签订了一份提到「秘密手艺」的合同——活字印刷的早期试验，可能就藏在这份合同背后。',
          '1448 年他回到美因茨，向亲戚借了 150 盾重开工坊；1450 年又从富商约翰·福斯特处借贷 800 盾——以这笔钱为股本，人类信息史上的关键设备开始运转。',
