          '三场革命踩在这两千万册上。宗教改革：1517 年路德把《九十五条论纲》贴上教堂门，几周内印刷传单传遍德意志——没有印刷机，路德只是又一个异端；路德本人称印刷是「上帝最高的恩赐」。科学革命：星表、解剖图、数据表第一次能「分毫不差」地传播——手抄时代以讹传讹的错漏链，被切断了。民族语言：方言词典、语法书、大众读物流通，各国的「标准语」被印出来。',
