          '1903 年，诺贝尔物理学奖授予贝克勒尔与居里夫妇——评奖名单最初没有玛丽，在皮埃尔的坚持下她才被加上。1911 年，她再以镭与钋的化学研究独享诺贝尔化学奖：第一个获得诺贝尔奖的女性，也是迄今唯一在两个不同科学领域获奖的人。索邦的讲席也来了：1906 年皮埃尔车祸去世后，她接过他的教职，成为索邦第一位女教授。',
