          '特斯拉 1856 年生在克罗地亚的塞尔维亚牧师家庭，格拉茨理工出身，精通八种语言，脑子里先做实验再动手。1882 年，他在布达佩斯的城市公园里一边背《浮士德》一边散步，脑海中突然浮现出旋转磁场的完整图景——用木棍在沙地上画图向同伴讲解。这个构想日后成为交流感应电动机的心脏。1884 年，他揣着推荐信与四美分抵达纽约，投奔爱迪生。',
