          '但一战给了他最惨的一跤：他力主的达达尼尔-加里波利战役（1915）伤亡惨重，被迫辞去海军大臣，一度以内阁不管部大臣之职坐冷板凳。他的办法是穿上军装，以少校身份亲赴西线战壕，指挥皇家苏格兰燧发枪团一个营——政客下放当营长，史不多见。这段战壕岁月让他的政敌闭了嘴，也让他终生对军事冒险的代价保持警觉——或者说，终生不改对军事冒险的偏爱，史家至今争论。',
