          '1519 年，宁王朱宸濠在南昌起兵十万，顺江直趋安庆，南京震动。身边无兵的王阳明假造文书，谎称各路大军十六万合围，宁王果然在南昌迟疑十余日不敢东下；他趁隙纠合兵勇，先抄南昌老巢，再鄱阳湖决战——从起兵到就擒，前后三十五天。事后他连夜改捷报，把首功让给武宗的亲征队伍：深知功高之祸。',
          '功成而谤至。权臣江彬等进谗，朝廷论功含糊，随他起兵的弟子冀元亨竟死于狱中，直到 1521 年世宗即位才封他新建伯。立德、立功、立言，他被后世称作三不朽的完人——完人的代价，是连平叛的功劳都要亲手让出去。',
