          '心学的影响跨过海去。日本幕末，阳明学成为维新志士的精神资源，佐久间象山、吉田松阴皆读《传习录》；据说海军大将东乡平八郎随身佩印「一生低首拜阳明」——此事未必可考，但明治前夜日本朝野竞谈阳明学，确是史实。',
