          '他做的第一件事是把部落拆掉。全部牧民编为九十五个千户，下设百户、十户，领主世袭而受大汗节制——血缘部落被军事行政组织取代，草原第一次有了国家的骨架。再建万人怯薛军，由各千户子弟充任，既是大汗禁卫，也是质子营与干部学校。',
          '国家还需要法律与文字。他颁布《大扎撒》法典，从禁污水源到保护商旅皆有明文；又命乃蛮降臣塔塔统阿以畏兀儿字母拼写蒙古语，蒙古人第一次有了自己的文字。他本人不识字，却为帝国造了纸和笔。',
