          '他的法典与宗教宽容影响了后来诸帝国的治理；他的名字成了权力的计量单位——波斯史家为他立传，罗斯编年史诅咒他，中亚史诗传唱他。二十世纪的民族主义时代，蒙古国把他立为国父，机场以他命名，货币上印着他的脸。',
          '草原曾把他视为无物，他却让草原成了世界的中心。成吉思汗的真正遗产不是血统，而是一个证明：秩序可以从最破碎的地方建立起来，只要分配、法度与忠诚的规则站得住——至于这秩序用多少生命交换，历史从未打过折扣。',
