          '翻山的代价买到战略上几乎不可能的东西：出其不意。罗马大军还在原定战场，汉尼拔已出现在波河平原，新附的高卢部落纷纷来投。当年冬天的特雷比亚河之战，他诱敌渡河，把冻僵的罗马军团几乎全歼——这是罗马人百年未见的惨败。',
          '前 217 年特拉西美诺湖，他把伏击做成艺术：大军藏进湖岸山道与晨雾，罗马执政官弗拉米尼的部队成纵队行军，前后被切断，三小时内死伤两万余，执政官阵亡。罗马惊呼「汉尼拔在城门口」——此后他真的常驻意大利，一住十五年。',
