          '罗马军团以厚重纵队压向中央，弧线被压成凹形，罗马人以为胜利在望；就在阵形挤成一团、失去挥剑空间的时刻，两翼的非洲重步兵向内旋转，骑兵追溃罗马侧翼后从背后合拢。正午之后，战场变成一具钳子：罗马阵亡五万以上，执政官战死，元老成员死伤八十人。',
          '军事史称坎尼为「完美会战」：以少围多、成建制全歼，两千年来每个学兵法的人都要复盘这一仗。然而战略上它没有换来城下之盟——罗马拒绝谈判，把奴隶与少年编入军团，禁止哀悼超过三十日。汉尼拔等着罗马求和，罗马的回答是把战争打到迦太基去。',
