          '战后他主政迦太基七年，整顿财政司法，把赔款如数缴清——政绩越好，罗马越不安，索人令随之而来。他出走流亡：先投塞琉古的安条克三世，再走比提尼亚；前 183 年罗马使节上门，他说，罗马人等一个老人死去等得不耐烦了，那就免了他们的耐心——随即服毒。九岁祭坛前的誓言，以死不落于罗马之手的方式闭合。',
