          '两千年里他成了军事天才的代名词：拿破仑研读他的战史，施里芬计划的扉页写着坎尼，两次大战的参谋部都在重演双翼合围。英语里至今保留着一种说法，把一次干净利落的歼灭战直接叫作「一次坎尼」。一个亡了国的将军，靠战术活过了所有胜利者。',
