          '他的早年史料稀薄。据马里口传，兄长阿布巴卡尔二世曾率两千艘船远航大西洋一去不返，穆萨先摄政后即位——一段真假难辨的插曲，出自宫廷史诗《松迪亚塔》系统的后世追记，姑妄听之。',
          '即位后的扩张实实在在：他夺取尼日尔河湾的加奥与廷巴克图，把商路重镇纳入版图，帝国疆域一度西起大西洋沿岸、东抵尼日尔河深处，是撒哈拉以南非洲史上最大的帝国之一。',
