          '朝觐也让他认清了世界。归国途中他带回学者与工匠，据载从格拉纳达请来建筑师萨希利，在廷巴克图与加奥修建泥砖清真寺——西非的萨赫勒建筑传统与伊斯兰工艺，从此合流。',
