          '少年赴欧洲：在马德里娶妻，回委内瑞拉后新婚妻子数月内死于热病，他发誓终身不再娶，此后果然未再娶。再游欧洲时正值拿破仑称帝，1804 年在巴黎他见到游历过西属美洲的洪堡，据载洪堡告诉他：殖民地条件成熟，缺的是组织者。这句话他记了一生。',
