          '1825 年上秘鲁建国，国名定为玻利维亚——一个国家以在世者的名字命名，史所罕见。玻利瓦尔为它起草宪法，设终身总统制：今天看是败笔，当时他以为制度要防的是党争，不是人。他多度颁布解放奴隶的法令，虽然执行迟缓，方向却在战争之初就已定下——这既得益于海地的条件，也得益于童年那本《社会契约论》。',
          '他梦想把整个西属美洲连成一体：大哥伦比亚居中，1826 年巴拿马大会发出「美洲联盟」的先声。如果成功，拉丁美洲将有一个相当于整个欧洲体量的联邦——这个方案在此后两百年里被反复提起，每一次提起，都伴随着「如果当年」的叹息。',
