    summary: '江户时代的浮世绘画家，《富岳三十六景》享誉世界。',
    paragraphs: [
      '1849 年，江户，一位八十八岁的画师躺在床上口述遗言：如果上苍再借我十年寿命，再借我五年，我就能成为真正的画家。他一生画了三万余幅版画与图绘，改过三十多个画号，搬了九十三次家；临死时手边还放着没画完的稿子。他叫葛饰北斋——画下那道全世界都认识的巨浪的人。',
    ],
    sections: [
      {
        heading: '「画狂老人」',
        paragraphs: [
          '北斋 1760 年生于江户，本名时太郎，据推测出身工匠阶层，六岁起就爱临摹一切形状——他晚年自述，自己一生被「画的鬼魂」附体。十九岁拜入浮世绘胜川派门下画演员绘，后因兼习他派画风被逐出师门：此后他没有再投靠任何一家，靠黄封面插图、狂歌绘本等零活为生。',
          '他的自我更新近乎暴烈：一生用过三十余个画号——春朗、北斋、宗理、戴斗、为一、画狂老人卍……每换一次号，等于宣布换一种画法；同时搬家九十三次，据载穷到把家当只当画材与书。晚年与同为画师的女儿阿荣同住陋巷，父女在灯下对着同一只水壶画速写。',
          '七十岁上他写下那句著名的自评：七十岁之前画的画都不值一提。他给自己排的日程是——八十岁渐明画理，九十岁看穿万物本性，百岁臻于神境，一百一十岁每一点每一线皆是活物。一份从不打算兑现的工期表，写尽这个人对「画」本身的贪婪。',
        ],
      },
      {
        heading: '神奈川冲浪里',
        paragraphs: [
          '1830 至 1833 年间，七十余岁的北斋推出《富岳三十六景》：同一座富士山，从浪底、林间、甲州山道、江户街市等角度反复观看，初版三十六景因大卖追加十景，共四十六幅。这是江户出版业的生意，也是艺术史的事件：一套面向大众的风景版画，单价约一碗荞麦面钱，却画出了后世奉为经典的构图。',
          '《神奈川冲浪里》是其中最著名的一幅：巨浪像兽爪一样罩住三艘押送船，浪花碎成千百只飞鸟，画面深处的富士山小得像一枚印章——毁灭的动与亘古的静，被塞进同一格画面。画浪用的普鲁士蓝是刚从欧洲传入的新颜料：这道浪的蓝色本身，就是东西洋在江户街头相遇的证据。',
          '狂放的浪其实是算出来的：后世研究者用圆规检测，这道卷曲由多个同心圆弧精密构成。而浪下小船上的水手伏得极低——在日本人的世界里，海与山之间，人的位置从来如此。北斋没有把人画成主角，也没有画成配角，画成了尺度。',
        ],
      },
      {
        heading: '江户的浮世绘师',
        paragraphs: [
          '浮世绘本质是一门出版生意：画师画版样，雕工刻版，刷工套色，出版人投资发行，一套版能印数千张。北斋是这条流水线上最高产的画师之一：美人绘、役者绘、风景绘、春画、绘本插图无所不作。他编绘的《北斋漫画》十数编，相扑、鸟兽、工匠、鬼怪无所不包——名为画谱，实为面向学徒与市民的万物图鉴。',
          '江户的市民文化养着这门手艺：歌舞伎名角的脸谱、吉原的花魁、东海道五十三次的旅途，浮世绘就是那个时代的印刷媒体；北斋与写乐、歌麿同列大师。他研究过西洋画法——透视、阴影、普鲁士蓝——也临过中国画与荷兰版画。北斋的方向从来不是「日本风」，而是怎么都行，只要画得更好。',
          '这种没有门派的贪婪，成了他后来征服世界的伏笔。同一时期，江户的出版业让图像第一次成为大众消费品：和中国的木版年画、欧洲的铜版画相比，浮世绘把「画画」变成了一门可以养活工匠的生意——北斋正是这门生意里站到最高处的人。',
        ],
      },
      {
        heading: '被欧洲发现的浪',
        paragraphs: [
          '1850 年代日本开港后，浮世绘随茶叶箱与商船涌入欧洲；1867 年巴黎世博会后，「日本主义」席卷巴黎。梵高临摹日本版画，莫奈收藏浮世绘，德彪西的《大海》总谱封面按他本人的要求印上《神奈川冲浪里》——一百年前江户街头一碗面钱的画，成了欧洲现代主义的教科书。',
          '那道浪此后长进全世界的视觉记忆：从各国博物馆的镇馆展签，到 2020 年新版日本护照的签证页——签证页印着北斋的二十四幅富士山，一本国际旅行证件把他的画发到每个出国的日本人手里。一个江户画师的构图，成了「日本」这个符号本身。',
          '北斋死时，浮世绘在江户是手艺，不是国宝；「国宝」是他死后世界给的封号。今天《神奈川冲浪里》的每一张原版印张都因手工刷印而墨色略异，散落各大博物馆——北斋若看见，大概仍不满意：他到死都想把下一张，画得更好一点。',
        ],
      },
    ],
