          '1589 年，经举荐他出任比萨大学数学教授，薪金在全校垫底，远低于神学与医学教授。传说他曾登上斜塔，扔下两颗重量不同的铁球证伪亚里士多德——此事同样最早见于学生记载，史家存疑；但他确曾在《论运动》手稿里系统质疑亚氏物理学。1592 年他转聘威尼斯共和国治下的帕多瓦大学，一住十八年，自称一生最快乐的岁月。',
