          '这本书真正的发明是方法：数学化的假设、受控的实验、理想化的模型。他早年在《试金者》（1623）里已经说过：宇宙这本宏大的书是用数学语言写成的。爱因斯坦后来称他为现代科学之父，理由不在那些观测，而在方法——牛顿的《原理》，正站在这本书的肩上。',
