          '软禁中的他失明、丧女，1642 年去世。托斯卡纳大公想把他葬入佛罗伦萨圣十字教堂主殿，教廷不许，只能先葬附属小室；1737 年才迁入正殿——迟到 95 年的正名。1992 年，教廷为伽利略案致歉，此时距那场审判已过去 359 年。',
