          '再评价集中在他的「现代性」：不是因为他「对抗教会」的姿态，而是因为他把真理的标准从权威挪到了实验与测量——观测和计算，说了才算。科学史家说，伽利略输掉了审判，却赢下了此后的一切科学：今天每一间实验室，都在继续替他做那场没有做完的辩护。',
