          '小猎犬号绕地球一周，航程约 6.4 万公里。在阿根廷，他挖出大地懒的化石——物种会灭绝，也会更替；在智利，一场地震让海岸抬升数米——背包里赖尔的《地质学原理》被一次次验证：地形靠缓慢累积的力量塑成。证据正在指向一个他不敢说出口的方向。',
          '决定性的一站是加拉帕戈斯群岛：相邻小岛上，同属的嘲鸫喙形各不相同。他起初没当回事，回国后翻检标本才看出蹊跷——如果每个岛都各造各的物种，造物主未免太随意。1837 年，他在笔记本上写下「转变」一词，旁边画了一棵分叉的树。',
          '突破口在 1838 年：他读到马尔萨斯《人口论》，食物不足与繁殖过剩的算术让他豁然——变异、竞争、选择，新物种的机制拼齐了。但接下来是二十年的沉默：理论写进密稿，只给寥寥几位友人看过。他清楚，这封信一旦拆开，掀掉的不只是博物学的屋顶。',
