          '有趣的是，全书通篇没有用「进化」一词，也很少谈人——只在结尾留下一句：人类的起源与历史将被照亮。他刻意避开最烫手的靶心，把火力集中在鸽子育种、藤壶解剖、雀鸟的喙这些没人能反驳的实证上。这不是胆怯，是战术：用农业与博物学的铁证，绕开神学的壕沟。',
