    summary: '为巴贝奇分析机写下第一段算法，预言计算机将超越计算。',
    paragraphs: [
      '1843 年，一位 27 岁的英国贵族女性为一台从未造出来的机器写下了「注记 G」：一张用打孔卡片驱动分析机计算伯努利数的操作序列——按今天程序员的共识，这是人类历史上第一段程序。她在注记里走得更远：这台机器可以处理的不只是数字，还能是符号、音符与任何可编码的对象。当时全英国能理解这件事的人屈指可数，她看得最深。一百多年后，美国国防部把一门编程语言命名为 Ada——用它向她还礼。',
    ],
    sections: [
      {
        heading: '诗人的女儿，数学家的学生',
        paragraphs: [
          '1815 年，阿达·拜伦生于伦敦，父亲是名满欧洲的诗人拜伦。母亲安娜贝拉受过良好的数学训练，婚后一年即与拜伦决裂，带着女儿离开；此后她终生警惕女儿「沾染父亲的诗性疯狂」，开出的药方是数学——七岁学几何，麻疹卧床、腿疾休养的日子也照学不误，家庭教师换了一任又一任。',
          '这份严苛合了槽：阿达对数学的痴迷是真诚的。17 岁那年，她在一场沙龙上见到 63 岁的查尔斯·巴贝奇和他的差分机模型——围观者看的是杂耍，她看到的是未来。此后她与这位「数字时代的先知」保持终身通信；1835 年她嫁给勋爵金，家庭安稳，通信与算式继续。',
        ],
      },
      {
        heading: '翻译后面的三倍注记',
        paragraphs: [
          '1840 年代初，意大利军官梅纳布雷亚用法文写了一篇分析机综述。1843 年，阿达把它译成英文，然后做了一件越界的事：在译文之后附上自己的七篇「注记」，篇幅三倍于原文，署名只用缩写 A.A.L.——在那个年代，女性用全名发表技术文章会被轻慢。',
          '注记 G 给出计算伯努利数的完整操作序列：不止列出公式，而是拆解到每一步该取哪个数、存进哪个存储单元、何时进位——这就是算法。她同时划出机器的边界：「分析机不能自主创造任何东西，只能执行我们命令它执行的事。」一百年后，图灵在《计算机器与智能》里专门回应了这条「洛芙莱斯的反驳」。',
        ],
      },
      {
        heading: '预言机器会谱曲',
        paragraphs: [
          '注记 A 里她写下那个著名的比喻：「分析机织出代数花样，正如雅卡尔织机织出花朵与树叶」——雅卡尔织机用打孔卡控制经纬，分析机用打孔卡控制运算。而她真正的突破是那个破圈之问：如果运算规则可以编码，数字凭什么只表示数量？机器或许可以合成任意复杂度的音乐。',
          '她与巴贝奇像一对材质不同的齿轮：巴贝奇是偏执的工程师，被英国财政与差分机拖垮一生；阿达是理论家与预言家，看得最远，却没有一件属于自己的机器。她也冲动——曾自创「赛马预测法」，结果输得几乎典当珠宝，靠母亲替她还债。天才与鲁莽，住在同一个脑子。',
        ],
      },
      {
        heading: '三十六岁的句点',
        paragraphs: [
          '婚后她接连生育三个孩子，身体却常年与病痛纠缠：子宫与脊椎的疾患让止痛剂与酒精成了日常。1852 年，子宫癌夺走她，年仅 36 岁；母亲与丈夫在她病中烧掉了部分书信——拜伦家族的「疯」名声，两边都不想再惹。她葬在诺丁汉郡的教堂，与从未谋面的父亲拜伦同眠。',
          '此后近百年，她几乎被遗忘——计算机史曾从巴贝奇讲起，只把她当作脚注。1953 年，学者鲍登主编的《比思考更快》重刊了她的注记，计算机先驱们惊讶地发现：第一段程序，与第一份「机器能做什么」的理论边界，一百多年前就已经写好。',
        ],
      },
      {
        heading: '被想起的先知',
        paragraphs: [
          '1980 年，美国国防部将其统一的高级语言命名为 Ada，以她致敬；从 2009 年起，每年 10 月第二个星期二是「阿达·洛芙莱斯日」，纪念理工领域尤其工程与编程中的女性。她的署名缩写 A.A.L. 也成了行业的双关：第一个程序，以匿名发布。',
          '学界对她仍有争论：一派认为注记主要是巴贝奇思想的忠实阐发，另一派（包括图灵）坚持她的「机器超越计算」之问是真正的理论飞跃。无论归功于谁，历史已经给出结论——第一个看清软件本质的人，是诗人的女儿、数学家的学生：两份遗产，她各取了一半。',
        ],
      },
    ],
