        paragraphs: [
          '约 1758 年，卡美哈美哈生于夏威夷大岛北科哈拉的酋长世家，幼年由叔父收养，习武、习祭祀，成年统领战团。传统编年把他出生与 1758 年哈雷彗星回归相系：传说预言「彗星之羽将扫灭酋长」，他活了下来，被族人视为应验天命（系年有争议，一说生于 1753 年前后）。',
          '他成长的世界正被撬开：1778 年库克船长的帆船抵达，铁器与火枪第一次进入群岛，次年库克本人在岛上的冲突中丧命。彼时诸岛四分五裂，大岛王位互争，各岛劫掠无常——欧洲人的火器，将成为新一轮胜负的砝码，就看谁先抓得住。',
        ],
