          '经济上他把群岛接进国际贸易：垄断檀香木采伐，对华出口换军火与工业品；与英美商人缔约时，他坚持以王国的名义——夏威夷以「国家」身份进入世界体系，正是从他手里开始。他还按传统不许外人购买土地，给群岛留了一道闸门——这道闸门在他身后才被打开。',
