          '再评价绕不开另一面：统一战争的伤亡没有统计，焚村、断崖与流亡贯穿诸岛；全球化也自他始——檀香木被伐到近乎绝种，外来疫病让原住民人口开始锐减。但在殖民窗口关闭之前，他保住了群岛的国家身份。一个靠断桨立誓的战士，最终成了主权与尊严的象征——太平洋史上，很少有人有这样的运气，更少有人有这样的手腕。',
