          '毕业后任《莱茵报》主编，一年内报纸被查封；1843 年赴巴黎办刊物，与合伙人闹翻，也在那里遇见恩格斯——曼彻斯特厂主之子。两人在咖啡馆连谈十天，从此四十年合著合编、互相垫钱。1848 年 2 月《共产党宣言》出版，第一句就是：一个幽灵，共产主义的幽灵，在欧洲游荡。',
