          '再评价在学院与现实之间分岔：政治经济学家承认他对资本主义结构性矛盾的诊断力，全球化、金融化与贫富分化，仍在用他的语汇分析；历史学家则清算计划经济的真实代价。海格特公墓的墓碑上刻着他自己的话——哲学家们只是用不同的方式解释世界，而问题在于改变世界。世界确实被改变了：这是 19 世纪任何哲学家都未曾有过的身后事。',
