          '1863 年 11 月，葛底斯堡演说以 272 个词把美国从「这些州组成的联合」重新定义为「民有、民治、民享的国家」——主权从州移交给国民。1864 年他以战时总统身份连任；1865 年 4 月 9 日，李将军在阿波马托克斯投降。四年内战死亡约 62 万人（新研究估至 75 万），超过美国其他所有战争之和，以联邦胜利告终。',
