          '这一步的代价是舆论的羞辱：「不终晚节」的讥评纷至沓来。她不辩解，只在给綦崇礼的谢启里把原委交代清楚。用一个牢狱之灾换回人身自由，在十二世纪的女性身上，这个选择激进得近乎现代——她一辈子都在做别人不敢做的事。',
