          '在日本他剪了辫子，先入弘文学院，1904年进仙台医学专门学校——中国人第一次进这所学校。教解剖学的藤野严九郎为他逐字修改笔记，这段师生情后来写成《藤野先生》。学医的动机很朴素：父亲死于庸医与偏方，他要医学救「像他父亲似的病人」。',
