          '最终是艺术留住了他：遗书里他写道，在作品没有全部完成之前，我不能离开这个世界。此后二十多年，他在逐渐全聋的状态里写完一生最重要的作品。耳朵关闭之后，音乐反而更自由——他不再为沙龙的即刻效果作曲，开始为自己的内在世界谱曲。',
