          '接下来是1808年的《第五「命运」》——开头的四个音符「短短短长」，成了西方文化里「抗争」的通用音效；同年《田园》用五个乐章给音乐画风景。他把交响曲、协奏曲、弦乐四重奏的形式边界一一推远：32首钢琴奏鸣曲，被称为钢琴文献的「新约圣经」。',
