    kicker: '被神宠爱又被神收回',
    summary: '三岁弹琴、六岁巡演的神童，歌剧与协奏曲的永恒坐标。',
    paragraphs: [
      '1762年，六岁的莫扎特被父亲带进维也纳的申布伦宫，在玛丽亚·特蕾莎女皇面前演奏。据传他在光可鉴人的地板上滑倒，一位小公主扶起了他，他立刻宣布：「你真好，我长大要娶你。」——据说那位公主是七岁的玛丽·安托瓦内特。轶事无从确证，但方向没错：这个孩子的整个童年，都在欧洲最豪华的房间里演出，观众是皇帝、皇后与王子。',
    ],
    sections: [
      {
        heading: '神童：父亲的事业，孩子的童年',
        paragraphs: [
          '1756年，沃尔夫冈·阿马德乌斯·莫扎特生于萨尔茨堡大主教辖区。父亲列奥波德是宫廷乐师，也是当时代最出色的音乐教育家：他3岁在键盘上摸索和弦，5岁写出第一首小步舞曲，6岁登台巡演。1763—1766年，父亲带着一双儿女横穿欧洲，巴黎、伦敦、阿姆斯特丹，一路演出一路上课。',
          '神童巡演是父亲的职业规划，也是孩子的全部童年，但收获是真的：他在伦敦师从J.C.巴赫，八岁写出第一部交响曲，十一岁试笔歌剧。1770年途经罗马，据载他凭一次听记，默写出梵蒂冈秘不外传的阿莱格里《求主垂怜》九声部总谱——十四岁的耳朵，已经是一台仪器。',
        ],
      },
      {
        heading: '决裂：从大主教家的仆人到自由作曲家',
        paragraphs: [
          '成年是莫扎特的第二次出生。1777年起他外出求职屡屡碰壁，母亲随行照顾，1778年病逝于巴黎——这是他一生的暗疮。回到萨尔茨堡，他忍着大主教的轻蔑做宫廷乐师，直到1781年维也纳之行彻底闹翻：据他自己的信，大主教的管家朝他屁股踹了一脚，他随即请辞——那封信又好气又好笑，是理解他性格的第一手材料。',
          '他选择留在维也纳做自由作曲家：接委约、教学生、办订票音乐会，成为德语世界最早摆脱宫廷供养的成功案例。自由的代价是收入颠簸——好年景他据估算位居维也纳音乐家前列，坏年景则不断写信向朋友告贷。他把钱花在公寓、台球与体面衣着上，账本永远追不上才华。',
        ],
      },
      {
        heading: '歌剧：仆人当主角，共济会登台',
        paragraphs: [
          '与脚本作家达·蓬特合作的三部曲，把歌剧从贵族消遣变成了社会喜剧：《费加罗的婚礼》（1786）让聪明的仆人站到戏的中心，顺手嘲讽了伯爵的特权；《唐璜》（1787）把诱惑与审判写进喜剧框架；《女人心》（1790）干脆把爱情怀疑论搬上舞台。这些剧首演时争论不断，此后两百年再没离开过全世界的歌剧院。',
          '1791年9月首演的《魔笛》用德语演唱、面向大众，裹着埃及背景讲共济会的启蒙寓言——莫扎特与脚本作者席卡内德都是共济会员。同年夏天他接到匿名委约写一部《安魂曲》，病中的他把这单生意当成了写给自己的告别。12月5日，《安魂曲》未完成，他去世，年35岁。',
        ],
      },
      {
        heading: '身后：神话与真正的遗产',
        paragraphs: [
          '死因至今众说纷纭：风湿热、肾病、当时的放血疗法……「对手萨列里下毒」纯属戏剧想象，源头是普希金的小戏与后世的电影。他葬于维也纳的普通合葬墓——那是约瑟夫二世推行的葬制，不是潦倒的证据。遗孀康丝坦策此后整理遗作、组织纪念演出，独自撑起了这个家的后半场。',
          '35年人生留下逾600部作品，克歇尔目录的K.编号至今是国际通行检索方式。「天才即流畅」的神话流传极广——他写信自称乐思络绎不绝、信手拈来，而手稿上反复修改的痕迹说明那仍是劳动。神话归神话，事实归事实：今天任何一间歌剧院的年度节目单，都绕不开这个名字。',
        ],
      },
    ],
