      '1778年3月30日，一位84岁的老人乘马车回到阔别二十八年的巴黎，人群把街道堵得水泄不通，有人爬上车辕只为看一眼他的脸。三天后他的新悲剧《伊兰纳》首演，谢幕时观众把桂冠戴到老人头上。伏尔泰等了一辈子的凯旋，来得这样晚——两个半月后，他去世。',
