          '1778年5月30日，伏尔泰去世。教会拒绝给他教会墓地，家人只能把遗体秘密运到塞利埃修道院下葬。1791年，大革命中的国民公会把他迁葬先贤祠，灵柩穿过巴黎，万人围观——他生前躲了一辈子当局，死后成了国家供奉的第一批「伟人」。',
          '那句传遍世界的「我不同意你说的每一个字，但我誓死保卫你说话的权利」，并非他的原话，而是1906年英国作家霍尔在《伏尔泰的朋友们》中对他立场的转述——以讹传讹两百年，恰好证明他的立场比他的原文更有生命力。宽容、言论自由、政教分离，今天写进各国宪法与《世界人权宣言》的常识，最早就是从这类小册子与书信里长出来的。',
